/** Research adapter only. All image detection, fitting and area comparisons call frozen Android code. */
public class LuminousCalibrationStudy {
 @SuppressWarnings("unchecked") static Map<String,Object> obj(Object x){return x==null?new LinkedHashMap<>(): (Map<String,Object>)x;}
 static Map<String,Object> map(Object... a){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)m.put((String)a[i],a[i+1]);return m;}
 static double num(Object x){return x==null?Double.NaN:((Number)x).doubleValue();}
 static double[] vec(Object x){if(x==null)return null;List<?> a=(List<?>)x;double[] p=new double[a.size()];for(int i=0;i<p.length;i++)p[i]=num(a.get(i));return p;}
 static double[][] poly(Object x){if(x==null)return null;List<?> a=(List<?>)x;double[][] p=new double[a.size()][];for(int i=0;i<p.length;i++)p[i]=vec(a.get(i));return p;}
 static String json(Object x){if(x==null)return "null";if(x instanceof Number)return Double.isFinite(((Number)x).doubleValue())?x.toString():"null";if(x instanceof Boolean)return x.toString();if(x instanceof Map){List<String> a=new ArrayList<>();for(Map.Entry<?,?> e:((Map<?,?>)x).entrySet())a.add(json(e.getKey().toString())+":"+json(e.getValue()));return "{"+String.join(",",a)+"}";}if(x instanceof Iterable){List<String> a=new ArrayList<>();for(Object e:(Iterable<?>)x)a.add(json(e));return "["+String.join(",",a)+"]";}if(x.getClass().isArray()){List<String> a=new ArrayList<>();for(int i=0;i<java.lang.reflect.Array.getLength(x);i++)a.add(json(java.lang.reflect.Array.get(x,i)));return "["+String.join(",",a)+"]";}return "\""+x.toString().replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
 static String sha(byte[] data)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}
 static Map<String,Object> metric(MarkerPolygonMismatch.Score s){if(s==null)return null;double extra=s.extraRegions().stream().mapToDouble(MarkerPolygonMismatch::area).sum(),missing=s.missingRegions().stream().mapToDouble(MarkerPolygonMismatch::area).sum();if(Math.abs(extra-s.extraArea)>1e-8||Math.abs(missing-s.missingArea)>1e-8||Math.abs(s.extraPct+s.missingPct-s.mismatchPct)>1e-9)throw new AssertionError("Region/area consistency");return map("expected_area_R2",s.expectedArea,"actual_area_R2",s.actualArea,"extra_pct",s.extraPct,"missing_pct",s.missingPct,"total_pct",s.mismatchPct,"expected_polygon",s.expectedPolygon,"actual_polygon",s.actualPolygon,"extra_regions",s.extraRegions(),"missing_regions",s.missingRegions());}
 static Map<String,Object> fit(LuminousPartialFit.Fit f,ModelSpec.Marker m,double[] ring){if(f==null)return null;return map("supported",f.usable(),"orientation",f.orientation,"angle_rad",f.angle,"center",f.center,"tip",f.tip,"radius_R",f.radius,"width_R",f.width,"height_R",f.height,"symmetry_pct",f.symmetry,"rms_px",f.rmsPx,"angle_span_deg",f.angleSpanDeg,"center_span_px",f.centerSpanPx,"radius_span_px",f.radiusSpanPx,"cross_normal",f.crossNormal,"cross_c_R",f.crossC,"ideal",f.ideal,"local_ideal",f.ideal==null||ring==null?null:LuminousGeometry.local(f.ideal,m,ring),"observed",f.observed,"segments",f.segments,"reason",f.reason);}
 static LuminousPartialFit.Fit restore(Map<String,Object> r){if(r.isEmpty())return null;LuminousPartialFit.Fit f=new LuminousPartialFit.Fit();f.orientation=Boolean.TRUE.equals(r.get("orientation"));f.angle=num(r.get("angle_rad"));f.center=vec(r.get("center"));f.tip=vec(r.get("tip"));f.radius=num(r.get("radius_R"));f.width=num(r.get("width_R"));f.height=num(r.get("height_R"));f.symmetry=num(r.get("symmetry_pct"));f.rmsPx=num(r.get("rms_px"));f.angleSpanDeg=num(r.get("angle_span_deg"));f.centerSpanPx=num(r.get("center_span_px"));f.radiusSpanPx=num(r.get("radius_span_px"));f.crossNormal=vec(r.get("cross_normal"));f.crossC=num(r.get("cross_c_R"));f.ideal=poly(r.get("ideal"));f.observed=poly(r.get("observed"));f.reason=String.valueOf(r.get("reason"));Object segments=r.get("segments");if(segments!=null)for(Object s:(List<?>)segments)f.segments.add(poly(s));return f;}
 static void extract(Path manifest,Path output)throws Exception{
  LuminousReference old=LuminousReference.load(ModelSpec.directory(HarnessModel.assetsRoot()),HarnessModel.spec().id);List<String> lines=Files.readAllLines(manifest);Files.createDirectories(output.getParent());
  try(PrintWriter writer=new PrintWriter(Files.newBufferedWriter(output))){for(int i=1;i<lines.size();i++){
   String[] row=lines.get(i).split(",",-1);Bitmap photo=Alpha96Calib.loadAlpha96(row[3]);Alpha99Pipeline.Output outer=Alpha99Pipeline.run(photo,HarnessModel.spec(),HarnessModel.ref());
   Map<String,Object> data=map("photo_id",row[0],"group_id",row[1],"split",row[2],"family",HarnessModel.spec().id,"cv_fold",row.length>4?row[4]:null,"primary_eligible",row.length>5?row[5]:null,"primary_photo",row.length>6?row[6]:null,"source_sha256",sha(Files.readAllBytes(Path.of(row[3]))),"working_width",photo.getWidth(),"working_height",photo.getHeight(),"pose_valid",outer.ok(),"pose_reason",outer.pose==null?"pose unavailable":outer.pose.reason);
   List<Object> markers=new ArrayList<>();data.put("markers",markers);
   if(outer.ok()){
    double[] ring=outer.measurement.ring!=null&&outer.measurement.ring.usable?outer.measurement.ring.model:null;String snapshot=LuminousValidation.snapshot(outer);
    data.putAll(map("input_evidence",outer.inputEvidence,"outer_snapshot_sha256",sha(snapshot.getBytes(java.nio.charset.StandardCharsets.UTF_8)),"H",outer.pose.homography,"ring",ring,"dial_radius_px",outer.measurement.dialRadiusPx,"ellipse_ratio",outer.pose.ellipseRatio,"edge_rms_px",outer.pose.edgeRms,"tick_rms_px",outer.pose.fitAfter,"ticks",outer.pose.detectedTicks,"complete_pairs",outer.pose.completePairs,"marker_branch_turn",outer.pose.markerBranchTurn));
    Map<Integer,LuminousMarkerDetector.Detection> detections=LuminousMarkerDetector.detect(photo,outer);
    if(!snapshot.equals(LuminousValidation.snapshot(outer)))throw new AssertionError("Outer measurement mutated");
    for(ModelSpec.Marker m:outer.model.markers){LuminousMarkerDetector.Detection d=detections.get(m.hour);LuminousMeasurement.Marker measured=new LuminousMeasurement.Marker(m,d,ring==null?null:old.expected(m,ring));Alpha99MarkerInterference.Check check=outer.checks==null?null:outer.checks.get(m.hour);MarkerMismatchResearch.Result om=outer.mismatch.get(m.hour);Alpha94MarkerMeasurement.Marker q=outer.measurement.atHour(m.hour);String status="";for(Alpha99Findings.Finding f:outer.summary.all)if(!f.dialWide&&f.hour==m.hour)status=f.status.toString();
     markers.add(map("hour",m.hour,"shape",m.kind(),"key",m.key,"observed_usable",d.usable(),"observed_polygon",d.polygon,"local_observed",d.usable()&&ring!=null?LuminousGeometry.local(d.polygon,m,ring):null,"reason",d.reason,"failure_code",d.failureCode,"diagnostics",d.attempts,"method",d.method,"boundary_spread_px",d.boundarySpreadPx,"rotation_spread_deg",d.rotationSpreadDeg,"edge_coverage",d.edgeCoverage,"contrast",d.contrast,"fit",fit(d.alignment,m,ring),"interference_clean",check!=null&&check.clean,"interference_reason",check==null?"unavailable":check.reason,"old_fitted",metric(measured.fittedScore),"old_alignment",metric(measured.alignmentScore),"old_observed",metric(measured.score),"old_direction_deg",LuminousValidation.fitDisplacement(measured,0).equals("")?null:measured.alignment!=null&&measured.alignment.orientation&&measured.expectedAlignment!=null&&measured.expectedAlignment.orientation?LuminousGeometry.angleDifference(measured.alignment.angle,measured.expectedAlignment.angle):null,"old_dx_R",LuminousValidation.fitDisplacement(measured,0),"old_dy_R",LuminousValidation.fitDisplacement(measured,1),"outer_status",status,"outer_rotation_deg",q==null?null:q.rotationDeg,"outer_calibrated_rotation_deg",m.shape==ModelSpec.Shape.BATON&&q!=null?q.rotationDeg-outer.reference.nominal(m.key+"_rot"):null,"outer_area_reason",om==null?null:om.reason,"outer_total_pct",om==null||!om.trusted()?null:om.score.mismatchPct));
    }
   }else{for(ModelSpec.Marker m:HarnessModel.spec().markers)markers.add(map("hour",m.hour,"shape",m.kind(),"observed_usable",false,"failure_code","POSE_UNAVAILABLE","reason",data.get("pose_reason")));}
   writer.println(json(data));writer.flush();System.err.println("extracted "+row[0]+" "+row[2]);
  }}
 }
 static Map<String,Object> evaluate(Map<String,Object> photo,Map<String,Object> references){
  Map<String,Object> result=new LinkedHashMap<>(photo);List<Object> measured=new ArrayList<>();result.put("markers",measured);Map<String,Object> model=obj(obj(references.get("models")).get(photo.get("family")));Map<String,Object> positions=obj(model.get("positions"));double[] ring=vec(photo.get("ring"));
  for(Object value:(List<?>)photo.get("markers")){Map<String,Object> raw=obj(value),r=new LinkedHashMap<>(raw);int hour=((Number)raw.get("hour")).intValue();ModelSpec.Marker spec=HarnessModel.spec().atHour(hour);Map<String,Object> reference=obj(positions.get(String.valueOf(hour)));LuminousMarkerDetector.Detection d=new LuminousMarkerDetector.Detection(hour);d.polygon=poly(raw.get("observed_polygon"));d.reason=String.valueOf(raw.get("reason"));d.alignment=restore(obj(raw.get("fit")));double[][] expected=ring==null?null:poly(reference.get("geometric_polygon"));if(expected!=null)expected=LuminousGeometry.placed(expected,spec,ring);
   LuminousMeasurement.Marker m=new LuminousMeasurement.Marker(spec,d,expected);double[][] footprint=ring==null?null:poly(reference.get("observed_polygon"));if(footprint!=null)footprint=LuminousGeometry.placed(footprint,spec,ring);
   r.putAll(map("new_geometric_reference",expected,"new_observed_reference",footprint,"new_fitted",metric(m.fittedScore),"new_alignment",metric(m.alignmentScore),"new_observed",metric(d.usable()&&footprint!=null?MarkerPolygonMismatch.compare(footprint,d.polygon):null),"new_dx_R",LuminousValidation.fitDisplacement(m,0),"new_dy_R",LuminousValidation.fitDisplacement(m,1),"new_direction_deg",m.alignment!=null&&m.alignment.orientation&&m.expectedAlignment!=null&&m.expectedAlignment.orientation?LuminousGeometry.angleDifference(m.alignment.angle,m.expectedAlignment.angle):null,"reference_geometric_groups",reference.get("geometric_groups"),"reference_observed_groups",reference.get("observed_groups"),"reference_status",expected==null?"insufficient_development_geometry_or_ring":"experimental"));measured.add(r);
  }return result;
 }
 static void score(Path raw,Path refs,Path output)throws Exception{Map<String,Object> references=obj(MiniJson.parse(Files.readString(refs)));try(PrintWriter w=new PrintWriter(Files.newBufferedWriter(output))){for(String line:Files.readAllLines(raw)){Map<String,Object> photo=obj(MiniJson.parse(line));String fold=System.getProperty("watchalign.study.fold");if(fold!=null&&(!"development".equals(photo.get("split"))||!fold.equals(photo.get("cv_fold"))||!"true".equals(photo.get("primary_eligible"))||!"true".equals(photo.get("primary_photo"))))continue;w.println(json(evaluate(photo,references)));}}}
 static void gallery(Path scored,Path manifest,Path select,Path dest)throws Exception{
  Files.createDirectories(dest);Map<String,String> paths=new HashMap<>();for(String s:Files.readAllLines(manifest).subList(1,Files.readAllLines(manifest).size())){String[] f=s.split(",",-1);paths.put(f[0],f[3]);}Set<String> chosen=new HashSet<>();for(String s:Files.readAllLines(select)){String[] parts=s.split(",");if(parts.length==2)chosen.add(parts[0]+","+(int)Double.parseDouble(parts[1]));}
  for(String line:Files.readAllLines(scored)){Map<String,Object> p=obj(MiniJson.parse(line));String id=String.valueOf(p.get("photo_id"));if(!paths.containsKey(id))continue;Bitmap photo=null,nativePhoto=null;Mat rgba=null;
   for(Object item:(List<?>)p.get("markers")){Map<String,Object> r=obj(item);int hour=((Number)r.get("hour")).intValue();if(!chosen.contains(id+","+hour))continue;if(photo==null){if(!sha(Files.readAllBytes(Path.of(paths.get(id)))).equals(p.get("source_sha256")))throw new AssertionError("Original bytes changed before gallery");photo=Alpha96Calib.loadAlpha96(paths.get(id));Mat full=org.opencv.imgcodecs.Imgcodecs.imread(paths.get(id),org.opencv.imgcodecs.Imgcodecs.IMREAD_COLOR);nativePhoto=Load.fromBgr(full);full.release();rgba=new Mat();Utils.bitmapToMat(photo,rgba);}double[] H=vec(p.get("H")),ring=vec(p.get("ring"));if(H==null)continue;ModelSpec.Marker spec=HarnessModel.spec().atHour(hour);double[] c=ExpectedMarkerOutline.moved(new double[][]{spec.masterPoint()},ring)[0];Mat crop=Alpha98Closeups.render(rgba,H,c[0],c[1],.19);Bitmap plain=Bitmap.createBitmap(480,480,Bitmap.Config.ARGB_8888);Utils.matToBitmap(crop,plain);crop.release();
    java.awt.image.BufferedImage canvas=new java.awt.image.BufferedImage(2400,720,java.awt.image.BufferedImage.TYPE_INT_RGB);java.awt.Graphics2D g=canvas.createGraphics();g.setColor(java.awt.Color.WHITE);g.drawString(id+" / "+p.get("family")+" / "+hour+" / "+p.get("split"),12,24);
    double[][] box=MarkerMismatchOverlay.project(new double[][]{{c[0]-.19,c[1]-.19},{c[0]+.19,c[1]-.19},{c[0]+.19,c[1]+.19},{c[0]-.19,c[1]+.19}},H);int left=nativePhoto.getWidth(),top=nativePhoto.getHeight(),right=0,bottom=0;for(double[] pt:box){pt[0]*=nativePhoto.getWidth()/(double)photo.getWidth();pt[1]*=nativePhoto.getHeight()/(double)photo.getHeight();}for(double[] pt:box){left=Math.min(left,(int)Math.floor(pt[0]));top=Math.min(top,(int)Math.floor(pt[1]));right=Math.max(right,(int)Math.ceil(pt[0]));bottom=Math.max(bottom,(int)Math.ceil(pt[1]));}left=Math.max(0,left);top=Math.max(0,top);right=Math.min(nativePhoto.getWidth(),right);bottom=Math.min(nativePhoto.getHeight(),bottom);java.awt.image.BufferedImage nativeCrop=nativePhoto.img.getSubimage(left,top,right-left,bottom-top);double factor=Math.min(480.0/nativeCrop.getWidth(),480.0/nativeCrop.getHeight());int nw=(int)(factor*nativeCrop.getWidth()),nh=(int)(factor*nativeCrop.getHeight());g.drawImage(nativeCrop,(480-nw)/2,50+(480-nh)/2,nw,nh,null);g.drawImage(plain.img,480,50,null);g.drawString("Original native crop (display scaling only)",12,550);g.drawString("Frozen perspective-corrected raw crop",492,550);
    String[] keys={"new_fitted","new_alignment","new_observed"};for(int k=0;k<3;k++){Map<String,Object> metric=obj(r.get(keys[k]));Bitmap marked=plain.copy(Bitmap.Config.ARGB_8888,true);double[][] e=poly(metric.get("expected_polygon")),a=poly(metric.get("actual_polygon"));MarkerPolygonMismatch.Score s=e==null||a==null?null:MarkerPolygonMismatch.compare(e,a);if(e==null)e=poly(r.get(k==2?"new_observed_reference":"new_geometric_reference"));if(s!=null&&Math.abs(s.mismatchPct-num(metric.get("total_pct")))>1e-9)throw new AssertionError("Gallery not same score");MarkerMismatchOverlay.closeup(marked,c[0],c[1],.19,new MarkerMismatchResearch.Result(s,s==null?"withheld":"measured",e));g.drawImage(marked.img,(k+2)*480,50,null);g.setColor(java.awt.Color.WHITE);g.drawString(new String[]{"FITTED GEOMETRIC","ALIGNMENT ONLY","OBSERVED PHYSICAL"}[k]+(s==null?" withheld":String.format(Locale.US," %.4f%%",s.mismatchPct)),(k+2)*480+12,550);if(s!=null)g.drawString(String.format(Locale.US,"extra %.4f%% + missing %.4f%%",s.extraPct,s.missingPct),(k+2)*480+12,575);}
    Map<String,Object> fit=obj(r.get("fit"));g.drawString("Fitted dx="+r.get("new_dx_R")+" R, dy="+r.get("new_dy_R")+" R, direction="+r.get("new_direction_deg")+" deg; R="+p.get("dial_radius_px")+" source px",12,608);g.drawString("Residual="+fit.get("rms_px")+" px; angle subset span="+fit.get("angle_span_deg")+" deg; circle subset centre/radius="+fit.get("center_span_px")+" / "+fit.get("radius_span_px")+" px; samples="+(fit.get("observed")==null?0:((List<?>)fit.get("observed")).size()),12,633);g.drawString(String.valueOf(fit.get("reason")),12,658);g.drawString("Observed: "+r.get("reason"),12,683);g.dispose();javax.imageio.ImageIO.write(canvas,"png",dest.resolve(id+"_"+hour+".png").toFile());System.err.println("rendered "+id+" "+hour);
   }if(rgba!=null)rgba.release();
  }
 }
 static void referenceSelfCheck(Path refs,Path output)throws Exception{
  Map<String,Object> root=obj(MiniJson.parse(Files.readString(refs))),positions=obj(obj(obj(root.get("models")).get(HarnessModel.spec().id)).get("positions"));
  try(PrintWriter csv=new PrintWriter(Files.newBufferedWriter(output))){csv.println("family,hour,shape,ideal_self_fitted_pct,ideal_self_alignment_pct,reference_refit_dx_R,reference_refit_dy_R,reference_refit_direction_deg");
   for(ModelSpec.Marker spec:HarnessModel.spec().markers){double[][] local=poly(obj(positions.get(String.valueOf(spec.hour))).get("geometric_polygon"));if(local==null)continue;double[][] e=LuminousGeometry.placed(local,spec,new double[]{0,0,0,0});LuminousPartialFit.Fit truth=new LuminousPartialFit.Fit();truth.ideal=e;truth.center=LuminousGeometry.centroid(e);truth.orientation=spec.shape!=ModelSpec.Shape.ROUND;
    if(spec.shape==ModelSpec.Shape.TRIANGLE){double mx=(e[1][0]+e[2][0])/2,my=(e[1][1]+e[2][1])/2;truth.angle=Math.atan2(e[0][1]-my,e[0][0]-mx);}
    else if(spec.shape==ModelSpec.Shape.BATON){double a=Math.atan2(e[3][1]-e[0][1],e[3][0]-e[0][0]),b=Math.atan2(e[2][1]-e[1][1],e[2][0]-e[1][0]);truth.angle=a+Math.toRadians(LuminousGeometry.angleDifference(b,a))/2;}
    LuminousMarkerDetector.Detection d=new LuminousMarkerDetector.Detection(spec.hour);d.alignment=truth;LuminousMeasurement.Marker m=new LuminousMeasurement.Marker(spec,d,e);if(m.fittedScore==null||Math.abs(m.fittedScore.mismatchPct)>1e-9)throw new AssertionError("Identical fitted polygons");
    LuminousValidation.emit(csv,new Object[]{HarnessModel.spec().id,spec.hour,spec.kind(),m.fittedScore.mismatchPct,m.alignmentScore==null?"":m.alignmentScore.mismatchPct,m.expectedAlignment.center==null?"":m.expectedAlignment.center[0]-truth.center[0],m.expectedAlignment.center==null?"":m.expectedAlignment.center[1]-truth.center[1],truth.orientation&&m.expectedAlignment.orientation?LuminousGeometry.angleDifference(m.expectedAlignment.angle,truth.angle):""});
   }
  }
 }
 public static void main(String[] a)throws Exception{nu.pattern.OpenCV.loadLocally();switch(a[0]){case "selfcheck":referenceSelfCheck(Path.of(a[1]),Path.of(a[2]));break;case "extract":extract(Path.of(a[1]),Path.of(a[2]));break;case "score":score(Path.of(a[1]),Path.of(a[2]),Path.of(a[3]));break;case "gallery":gallery(Path.of(a[1]),Path.of(a[2]),Path.of(a[3]),Path.of(a[4]));break;default:throw new IllegalArgumentException("extract/score/gallery");}}
}
